package cache

import (
    "context"
    "encoding/json"
    "fmt"
    "time"
)

func (s Store) Get(ctx context.Context, id string) (Order, error) {
    key := "order:" + id
    if payload, err := s.cache.Get(ctx, key).Bytes(); err == nil {
        var out Order
        if json.Unmarshal(payload, &out) == nil { return out, nil }
    }
    out, err := s.primary.Get(ctx, id)
    if err != nil { return Order{}, fmt.Errorf("primary get: %w", err) }
    if payload, err := json.Marshal(out); err == nil {
        _ = s.cache.Set(ctx, key, payload, 5*time.Minute).Err()
    }
    return out, nil
}

