package job

import (
    "context"
    "errors"
)

func Decide(err error, attempt, max int) Action {
    if err == nil { return Ack }
    if errors.Is(err, context.Canceled) { return Drop }
    if errors.Is(err, ErrInvalid) { return DeadLetter }
    if attempt < max { return Retry }
    return DeadLetter
}
